#include <item/StorageRuntime.hpp>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
using namespace auriga::item;namespace f=persistent_item_fixture;namespace p=item_catalog_fixture;
namespace {
unsigned checks=0;void Check(bool v,const char* why){checks++;if(!v)throw std::runtime_error(why);}
void Run(const std::filesystem::path& golden){const auto c=BuildItemCatalog(f::Catalog()).value();const auto actor=f::Character();const ItemOwner account{ItemOwnerKind::Account,77},guild{ItemOwnerKind::Guild,9},recipient{ItemOwnerKind::Character,88};std::vector fences{ItemOwnerFence{actor,1,1},ItemOwnerFence{account,1,1},ItemOwnerFence{guild,1,1},ItemOwnerFence{recipient,1,1}};std::vector layouts{f::Inventory(),ItemStorageLayout{{account,ItemStorageKind::Safebox,1},5,9,2},ItemStorageLayout{{account,ItemStorageKind::Mall,1},5,9,2},ItemStorageLayout{{guild,ItemStorageKind::GuildStorage,1},5,9,2},ItemStorageLayout{{actor,ItemStorageKind::Mail,1},5,9,2},ItemStorageLayout{{actor,ItemStorageKind::PendingAward,1},5,9,2},ItemStorageLayout{{recipient,ItemStorageKind::Mail,1},5,9,2}};auto sword=f::Sword(1);sword.attributes.lockedSlot.reset();auto leather=f::Leather(2);leather.count=20;PersistentItem coin{ItemInstanceId::Create(3).value(),p::CoinVoucher(),actor};coin.count=5;coin.placement=ItemPlacement{ItemStorageKind::Inventory,1,3};std::vector all{sword,leather,coin};std::vector wallets{f::Gold(),ItemWallet{account,WalletCurrency::DragonCoin,1,200}};StorageActor a{42,77,9,{120,0,0},true,true,true,true};std::array ids{ItemInstanceId::Create(10).value(),ItemInstanceId::Create(11).value()};
    const auto make=[&](StorageChoice q){return MakeStorageCommit(*c,{33},fences,layouts,all,wallets,a,q,ids);};StorageChoice bank{StorageRoute::Bank,StorageCommand::Deposit,1};auto deposited=make(bank);Check(deposited.has_value(),"rich weapon deposits");auto stored=deposited->commit.items[0].after;Check(stored.owner==account && stored.id==sword.id && stored.attributes==sword.attributes && stored.stones==sword.stones && stored.refinementLevel==9,"bank preserves full state and identity");all[0]=stored;bank.command=StorageCommand::Withdraw;auto withdrawn=make(bank);Check(withdrawn && withdrawn->commit.items[0].after.owner==actor && withdrawn->commit.items[0].after.attributes==sword.attributes,"same rich instance withdraws");all[0]=sword;
    bank={StorageRoute::Bank,StorageCommand::Deposit,2,7};auto split=make(bank);Check(split && split->commit.items.size()==2 && split->commit.items[0].after.count==13 && split->commit.items[1].after.id.Value()==10 && split->commit.items[1].after.count==7,"partial stack has one reserved identity and conserves units");
    a.bankInRange=false;Check(!make(bank),"bank requires nearby keeper");a.bankInRange=true;a.account=78;Check(!make(bank),"foreign account has no authorized fence");a.account=77;
    all[0].boundTo=actor;bank={StorageRoute::Bank,StorageCommand::Deposit,1};auto bound=make(bank);Check(bound && bound->commit.items[0].after.boundTo==actor,"own bank retains character binding");all[0]=bound->commit.items[0].after;auto other=a;a.pid=43;fences[0].owner.id=43;bank.command=StorageCommand::Withdraw;Check(!make(bank),"same-account alt cannot withdraw another character's bound item");a=other;fences[0].owner=actor;all[0]=sword;
    StorageChoice gs{StorageRoute::Guild,StorageCommand::Deposit,1};Check(make(gs).has_value(),"member guild deposit");a.guildMember=false;Check(!make(gs),"non-member denied");a.guildMember=true;all[0]=make(gs)->commit.items[0].after;gs.command=StorageCommand::Withdraw;a.guildLeader=false;Check(!make(gs),"member cannot take leader-only guild items");a.guildLeader=true;Check(make(gs).has_value(),"leader guild withdrawal");all[0]=sword;
    StorageChoice send{StorageRoute::Mail,StorageCommand::Send,1,0,UINT32_MAX,88};auto mail=make(send);Check(mail && mail->commit.items[0].after.owner==recipient && mail->commit.items[0].after.placement->kind==ItemStorageKind::Mail,"mail transfers directly to recipient owner");all[0].boundTo=actor;Check(!make(send),"bound mail denied");all[0]=sword;
    for(auto route:{StorageRoute::Mall,StorageRoute::Mail,StorageRoute::Awards}){auto saved=all[0];all[0].owner=route==StorageRoute::Mall?account:actor;all[0].placement=ItemPlacement{route==StorageRoute::Mall?ItemStorageKind::Mall:route==StorageRoute::Mail?ItemStorageKind::Mail:ItemStorageKind::PendingAward,1,0};if(route==StorageRoute::Mall)all[0].boundTo=account;auto take=make({route,StorageCommand::Withdraw,1});Check(take && take->commit.items[0].after.owner==actor && take->commit.items[0].after.id==sword.id,"delivery retains exact instance");if(route==StorageRoute::Mall)Check(take->commit.items[0].after.boundTo==actor,"mall acquire binding follows first claiming character");all[0]=saved;Check(!make({route,StorageCommand::Deposit,1}),"delivery stores refuse player deposits");}
    auto redeem=make({StorageRoute::Wallet,StorageCommand::Redeem,3,2});Check(redeem && redeem->amount==200 && redeem->commit.wallets[0].after.balance==400 && redeem->commit.items[0].after.count==3,"voucher credits account rather than character");auto mint=make({StorageRoute::Wallet,StorageCommand::Mint,p::CoinVoucher().LocalId(),1});Check(mint && mint->commit.wallets[0].after.balance==100 && mint->commit.items[0].after.count==6,"wallet mints an equivalent voucher without duplicating balance");Check(!make({StorageRoute::Wallet,StorageCommand::Mint,p::CoinVoucher().LocalId(),3}),"overdraft refuses item grant");
    auto altered=redeem->commit;altered.wallets[0].after.balance++;Check(!ValidateItemCommit(*c,altered),"wallet credit tampering denied");altered=deposited->commit;altered.items[0].after.attributes={};Check(!ValidateItemCommit(*c,altered),"storage payload tampering denied");for(unsigned n=0;n<redeem->commit.result.size();n++){altered=redeem->commit;altered.result.resize(n);Check(!ValidateItemCommit(*c,altered),"truncated storage decision denied");}
    StorageSnapshot view;view.actor=a;view.route=StorageRoute::Bank;view.owner=account;view.items={stored};view.layouts={layouts[1]};view.canDeposit=view.canWithdraw=true;view.coins=200;view.walletRevision=1;auto wire=EncodeStorageSnapshot(*c,view);Check(wire && (*wire)[0]==std::byte{201},"native storage snapshot");if(!golden.empty()){std::filesystem::create_directories(golden);std::ofstream out(golden/"typed_storage_v1.hex");for(auto b:*wire)out<<std::hex<<std::setfill('0')<<std::setw(2)<<std::to_integer<unsigned>(b);out<<'\n';Check(out.good(),"storage golden");}
}
}
int main(int argc,char** argv){try{Run(argc==3 && std::string_view(argv[1])=="--write-golden"?std::filesystem::path(argv[2]):std::filesystem::path{});std::cout<<"STORAGE_RUNTIME_TESTS=SUCCESS checks="<<checks<<'\n';return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
